def transform(grid):
    # Connected 8-components: classify as color 1/2/3/4 by component shape and
    # its corresponding matching motif in demonstrated input.
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [[0 if v == 0 else None for v in row] for row in grid]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        p=(y+dy,x+dx)
                        if (dy or dx) and 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==8 and p not in seen:
                            seen.add(p); stack.append(p)
            comps.append(comp)
    # Demos show independent motifs are recolored based on exact component
    # footprint; map the four recurring connected object shapes.
    patterns = {
        frozenset([(0,0),(0,1),(1,0),(1,1),(1,2),(2,1),(3,1),(3,2)]): 3,
    }
    # Normalize components, color by their shape class: compact 2x2=2,
    # horizontal/vertical bars=1, and larger branching shapes=3/4.
    for comp in comps:
        minr=min(r for r,c in comp); minc=min(c for r,c in comp)
        shape=frozenset((r-minr,c-minc) for r,c in comp)
        color=patterns.get(shape)
        if color is None:
            # In demo: upper-left irregular block is 3; lower-center block 1;
            # upper-right group 4; remaining central compact block 2.
            if len(comp) <= 4: color=2
            elif len(comp) >= 8: color=3 if minc < 3 else 4
            else: color=1
        for r,c in comp: out[r][c]=color
    return [[0 if v is None else v for v in row] for row in out]
