 "content": "def transform(grid):
    """Color disjoint 2x2 square/L triomino motifs in an 8-grid."""
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    # Colors observed in the demonstrations: full square=1; missing TL=2,
    # missing BL=3, missing TR=4. (The fourth L orientation is color 5.)
    missing_to_color = {(0, 0): 2, (1, 0): 3, (0, 1): 4, (1, 1): 5}
    motifs = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            present = box & cells
            if len(present) == 4:
                motifs.append((present, 1))
            elif len(present) == 3:
                missing = next(iter(box - present))
                motifs.append((present, missing_to_color[(missing[0] - r, missing[1] - c)]))

    by_cell = {p: [] for p in cells}
    for i, (shape, color) in enumerate(motifs):
        for p in shape:
            by_cell[p].append(i)

    def search(left, chosen):
        if not left:
            return chosen
        p = min(left, key=lambda x: sum(motifs[i][0] <= left for i in by_cell[x]))
        for i in by_cell[p]:
            shape, color = motifs[i]
            if shape <= left:
                ans = search(left - shape, chosen + [(shape, color)])
                if ans is not None:
                    return ans
        return None

    tiling = search(cells, [])
    if tiling is None:
        raise ValueError('8-cells cannot be tiled by 2x2 square/L motifs')
    out = [[0] * w for _ in range(h)]
    for shape, color in tiling:
        for r, c in shape:
            out[r][c] = color
    return out
